INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1000101, 2, "ふっふっふ、これでカヤぴぃとボスを見返してやるです！", "vo_minigame_1004_top_1_000", "vo_minigame_1004", 10001, 1);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1000201, 2, "しりとりでの戦い、お兄さんにも手伝ってもらうです", "vo_minigame_1004_top_1_003", "vo_minigame_1004", 10002, 1);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1000301, 1, "どんなケンカも売られた以上は買うのが喧嘩屋だ！やってやるぜ！", "vo_minigame_1004_top_1_004", "vo_minigame_1004", 10003, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1000401, 1, "石板でしりとりか……イノリのヤツおもしろいこと考えるな", "vo_minigame_1004_top_1_005", "vo_minigame_1004", 10004, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1000501, 1, "しりとりだろうがなんだろうが返り討ちにしてやるぜ", "vo_minigame_1004_top_1_006", "vo_minigame_1004", 10005, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1000601, 2, "ぐもも……（オデ、ハラヘッタ）", "vo_minigame_1004_top_1_007", "vo_minigame_1004", 10006, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1000701, 2, "ぐもももも（シリトリ タノシイ）", "vo_minigame_1004_top_1_008", "vo_minigame_1004", 10007, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1000801, 2, "ぐもももも！（イノリ イイヤツ）", "vo_minigame_1004_top_1_009", "vo_minigame_1004", 10008, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1000901, 2, "カヤぴぃ相手でも手加減しないです", "vo_minigame_1004_top_2_010", "vo_minigame_1004", 10009, 1);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1000902, 1, "上等だ！やるからには本気で来いよな", "vo_minigame_1004_top_2_011", "vo_minigame_1004", 10009, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001001, 2, "カヤぴぃ、謝るなら今のうちです", "vo_minigame_1004_top_2_012", "vo_minigame_1004", 10010, 1);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001002, 1, "イノリこそ泣きを入れるなら今のうちだぜ？", "vo_minigame_1004_top_2_013", "vo_minigame_1004", 10010, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001101, 2, "カヤぴぃ、これからは知性の時代ですよ？", "vo_minigame_1004_top_2_014", "vo_minigame_1004", 10011, 1);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001102, 1, "待て！オレがバカみたいにいうな！！", "vo_minigame_1004_top_2_015", "vo_minigame_1004", 10011, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001201, 1, "さあ、あたしたちの力を見せてやるです", "vo_minigame_1004_top_2_016", "vo_minigame_1004", 10012, 1);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001202, 2, "ぐも！（マカセロ！）", "vo_minigame_1004_top_2_017", "vo_minigame_1004", 10012, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001301, 1, "よしよし、いいですようまくできたらチョコをあげるです！", "vo_minigame_1004_top_2_018", "vo_minigame_1004", 10013, 1);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001302, 2, "ぐも！（オデ チョコスキ）", "vo_minigame_1004_top_2_019", "vo_minigame_1004", 10013, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001401, 1, "なあイノリ……もしかして当初の目的見失ってないよな？", "vo_minigame_1004_top_2_023", "vo_minigame_1004", 10014, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001402, 2, "もちろん覚えてるですカヤぴぃを倒し我々の知能を証明するです", "vo_minigame_1004_top_2_024", "vo_minigame_1004", 10014, 1);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001501, 1, "いくらイノリ相手でも勝ちを譲る気はないからな！", "vo_minigame_1004_top_2_025", "vo_minigame_1004", 10015, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001502, 2, "望むところです手加減はなしですよ", "vo_minigame_1004_top_2_026", "vo_minigame_1004", 10015, 1);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001601, 1, "へっ、なかなかやるじゃねえか", "vo_minigame_1004_top_2_027", "vo_minigame_1004", 10016, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001602, 2, "カヤぴぃも思ったよりやるですね！", "vo_minigame_1004_top_2_028", "vo_minigame_1004", 10016, 1);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001701, 1, "お～い、ドラゴンもどき？", "vo_minigame_1004_top_2_029", "vo_minigame_1004", 10017, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001702, 2, "ぐもっ！？（ヒッ！）", "vo_minigame_1004_top_2_030", "vo_minigame_1004", 10017, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001801, 1, "いやあ、あんときは悪かったなはっはっは", "vo_minigame_1004_top_2_031", "vo_minigame_1004", 10018, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001802, 2, "ぐももも……（かやピィ コワカッタ）", "vo_minigame_1004_top_2_032", "vo_minigame_1004", 10018, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001901, 1, "お前ってさ……ほんとマヌケな顔してるよな", "vo_minigame_1004_top_2_033", "vo_minigame_1004", 10019, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1001902, 2, "ぐも……（オマエガ イウカ）", "vo_minigame_1004_top_2_034", "vo_minigame_1004", 10019, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002001, 2, "ぐも……（ハラヘッタ チョコホシイ）", "vo_minigame_1004_top_2_044", "vo_minigame_1004", 10020, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002002, 1, "なんだ？眠いのか？", "vo_minigame_1004_top_2_045", "vo_minigame_1004", 10020, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002101, 2, "ぐもも（コイツ……キケン）", "vo_minigame_1004_top_2_046", "vo_minigame_1004", 10021, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002102, 1, "うん？　なんだ？オレの舎弟にでもなりたいのか？", "vo_minigame_1004_top_2_047", "vo_minigame_1004", 10021, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002201, 2, "ぐも…（かやピィノウキン）", "vo_minigame_1004_top_2_048", "vo_minigame_1004", 10022, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002202, 1, "おい、今失礼なこと考えてるだろ？", "vo_minigame_1004_top_2_049", "vo_minigame_1004", 10022, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002301, 1, "なあ、これいつまで続けるんだ？", "vo_minigame_1004_top_3_058", "vo_minigame_1004", 10023, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002302, 2, "カヤぴぃが降参するまでです！", "vo_minigame_1004_top_3_059", "vo_minigame_1004", 10023, 1);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002303, 2, "ぐもも！（コウサンシロ！）", "vo_minigame_1004_top_3_060", "vo_minigame_1004", 10023, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002401, 2, "ぐも！（イノリ チョコホシイ）", "vo_minigame_1004_top_3_065", "vo_minigame_1004", 10024, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002402, 1, "しょうがないですね、食べ過ぎはダメですよ", "vo_minigame_1004_top_3_066", "vo_minigame_1004", 10024, 1);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002403, 1, "土産のチョコ、そうとう気に入ったみたいだな", "vo_minigame_1004_top_3_067", "vo_minigame_1004", 10024, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002501, 2, "ぐも！（かやピィニハ マケナイ！）", "vo_minigame_1004_top_3_068", "vo_minigame_1004", 10025, 3);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002502, 1, "お？なんだ？腹でも減ってるのか？", "vo_minigame_1004_top_3_069", "vo_minigame_1004", 10025, 2);
INSERT INTO `v1_ffae47052ec356b6185a5280603046a86bbb69ec6190bdc51f3faca56b12b00e` VALUES (1002503, 2, "……全然話が通じてないです", "vo_minigame_1004_top_3_070", "vo_minigame_1004", 10025, 1);
